		slots[0] = window is null ? 0UL : window.Pointer;
		int status = Bindings.table.uiSystemWantsKeyboard(slots, slots + 1);
		if (status != Bridge.OK) {
			throw Bridge.Failure(status, "UISystem.WantsKeyboard");
		}
		return slots[1] != 0;
	}

